// Schemas for third-party content packs (src/content/packs/<pack-id>/*.json).
// Packs are generated by scripts/convert_*.py from MIT-licensed repos; see THIRD_PARTY_NOTICES.md.
// Every pack ships a pack.json with license/attribution metadata that the UI must be able to show.
import { z } from 'zod'
import { CefrSchema } from './content'

const SlugSchema = z.string().regex(/^[a-z0-9][a-z0-9-]*$/)

// ---- pack.json (shared by all packs) ----

export const PackMetaSchema = z.object({
  id: SlugSchema,
  name: z.string().min(1),
  version: z.string().regex(/^\d+\.\d+\.\d+$/),
  license: z.literal('MIT'),
  source: z.url(),
  commit: z.string().regex(/^[0-9a-f]{7,40}$/),
  copyright: z.string().min(1),
  attribution: z.string().min(1),
  files: z.array(z.string().regex(/^[a-z0-9-]+\.json$/)).min(1),
  content_sha256: z.string().regex(/^[0-9a-f]{64}$/),
  converted_at: z.string().min(1),
})
export type PackMeta = z.infer<typeof PackMetaSchema>

// ---- sprigo-en-syllabus/syllabus.json ----

// Activity type ids as used by Sprigo (kept as plain strings so new upstream types do not break loading).
export const SYLLABUS_ACTIVITY_TYPES = [
  'learn',
  'translate',
  'word_select',
  'match',
  'word_bank',
  'fill_blank',
  'multiple_choice',
  'listen_type',
  'listen_select',
  'image_select',
  'sentence_complete',
  'error_correct',
  'dialogue',
  'speak',
  'story',
  'roleplay',
  'video_call',
] as const

export const SyllabusActivitySchema = z.object({
  type: z.string().min(1),
  count: z.number().int().min(1),
  // Optional hints for activity generation (e.g. dialogue scenario and learner goal).
  scenario: z.string().min(1).optional(),
  goal: z.string().min(1).optional(),
})
export type SyllabusActivity = z.infer<typeof SyllabusActivitySchema>

export const SyllabusLessonSchema = z.object({
  id: SlugSchema,
  sourceId: z.string().min(1),
  unitId: SlugSchema,
  order: z.number().int().min(1),
  cefr: CefrSchema,
  title: z.string().min(1),
  description: z.string().min(1).nullable(),
  // Grammar patterns; `{name}`-style placeholders mark slots to fill.
  grammar: z.array(z.string().min(1)),
  vocabulary: z.array(z.string().min(1)),
  activityTypes: z.array(z.string().min(1)).min(1),
  activities: z.array(SyllabusActivitySchema).min(1),
})
export type SyllabusLesson = z.infer<typeof SyllabusLessonSchema>

export const SyllabusUnitSchema = z.object({
  id: SlugSchema,
  sourceId: z.string().min(1),
  order: z.number().int().min(1),
  cefr: CefrSchema,
  title: z.string().min(1),
  description: z.string().min(1).nullable(),
  icon: z.string().min(1).nullable(),
  lessons: z.array(SyllabusLessonSchema).min(1),
})
export type SyllabusUnit = z.infer<typeof SyllabusUnitSchema>

export const SyllabusCheckpointSchema = z.object({
  title: z.string().min(1),
  requiredScore: z.number().min(0).max(100),
  activities: z.array(SyllabusActivitySchema).min(1),
})
export type SyllabusCheckpoint = z.infer<typeof SyllabusCheckpointSchema>

export const SyllabusLevelSchema = z.object({
  cefr: CefrSchema,
  title: z.string().min(1),
  canDo: z.string().min(1).nullable(),
  units: z.array(SyllabusUnitSchema).min(1),
  checkpoint: SyllabusCheckpointSchema.nullable(),
})
export type SyllabusLevel = z.infer<typeof SyllabusLevelSchema>

export const SyllabusPackSchema = z
  .array(SyllabusLevelSchema)
  .min(1)
  .refine(
    (levels) => {
      const ids = levels.flatMap((l) => l.units.flatMap((u) => u.lessons.map((s) => s.id)))
      return new Set(ids).size === ids.length
    },
    { message: 'lesson ids must be unique across the syllabus' },
  )
export type SyllabusPack = z.infer<typeof SyllabusPackSchema>

// ---- cadence-pronunciation/phonemes.json ----

export const PHONEME_DIFFICULTIES = ['beginner', 'intermediate', 'advanced'] as const

export const PhonemeEntrySchema = z.object({
  symbol: z.string().min(1),
  ipa: z.string().min(1),
  label: z.string().min(1),
  category: z.string().min(1),
  difficulty: z.enum(PHONEME_DIFFICULTIES).nullable(),
  keywords: z.array(z.string().min(1)),
  exampleWords: z.array(z.string().min(1)).min(1),
  spellingPatterns: z.array(z.string().min(1)),
  articulation: z.string().min(1).nullable(),
  learnerTip: z.string().min(1).nullable(),
  commonErrors: z.array(z.string().min(1)),
  minimalPairs: z.array(z.array(z.string().min(1)).length(2)),
  dialectNote: z.string().min(1).nullable(),
  // Original B&T English note for Vietnamese learners (not from the upstream source).
  viNote: z.string().min(1).nullable(),
})
export type PhonemeEntry = z.infer<typeof PhonemeEntrySchema>

export const PhonemeCatalogSchema = z.array(PhonemeEntrySchema).min(1)
export type PhonemeCatalog = z.infer<typeof PhonemeCatalogSchema>

// ---- cadence-pronunciation/modules.json ----

export const PronunciationWordSchema = z.object({
  word: z.string().min(1),
  // Space-separated IPA phonemes, e.g. 'k æ t'.
  ipa: z.string().min(1),
  phonemes: z.array(z.string().min(1)).min(1),
})
export type PronunciationWord = z.infer<typeof PronunciationWordSchema>

export const PronunciationLessonSchema = z.object({
  id: SlugSchema,
  title: z.string().min(1),
  type: z.enum(['theory', 'practice', 'exam']),
  order: z.number().int().min(1),
  // Upstream theory markup (simple h2/p/ul/li/strong/em); sanitise before rendering.
  theoryHtml: z.string().min(1).nullable(),
  words: z.array(PronunciationWordSchema),
})
export type PronunciationLesson = z.infer<typeof PronunciationLessonSchema>

export const PronunciationModuleSchema = z.object({
  id: SlugSchema,
  order: z.number().int().min(1),
  title: z.string().min(1),
  description: z.string().min(1),
  phonemeFocus: z.array(z.string().min(1)).min(1),
  focusSymbols: z.array(z.string().min(1)).min(1),
  lessons: z.array(PronunciationLessonSchema).min(1),
})
export type PronunciationModule = z.infer<typeof PronunciationModuleSchema>

export const PronunciationModulesSchema = z.array(PronunciationModuleSchema).min(1)

// ---- cadence-pronunciation/targets.json ----

export const PracticeSegmentSchema = z
  .object({ text: z.string().min(1), start: z.number().int().min(0), end: z.number().int().min(0) })
  .refine((s) => s.end >= s.start, { message: 'segment end before start' })

export const PracticeTargetSchema = z.object({
  word: z.string().min(1),
  ipa: z.string().min(1),
  phonemes: z.array(z.string().min(1)).min(1),
  category: z.string().min(1),
  focusPhoneme: z.string().min(1),
  cue: z.string().min(1).nullable(),
  // Spans of the written word mapped to phoneme index ranges [start, end).
  segments: z.array(PracticeSegmentSchema),
})
export type PracticeTarget = z.infer<typeof PracticeTargetSchema>

export const PracticeTargetsSchema = z.object({
  categories: z.record(z.string(), z.string()),
  words: z.array(PracticeTargetSchema).min(1),
})
export type PracticeTargets = z.infer<typeof PracticeTargetsSchema>

// ---- cadence-pronunciation/conversations.json ----

export const ConversationTurnSchema = z.object({
  id: z.string().min(1),
  coachMessage: z.string().min(1),
  userPrompt: z.string().min(1),
  expectedResponse: z.string().min(1),
  coachingCue: z.string().min(1),
})
export type ConversationTurn = z.infer<typeof ConversationTurnSchema>

export const ConversationScenarioSchema = z.object({
  id: SlugSchema,
  order: z.number().int().min(1),
  title: z.string().min(1),
  // Upstream level label, may carry a '+' (e.g. 'B1+'); `cefr` is the base level.
  level: z.string().regex(/^[ABC][12]\+?$/),
  cefr: CefrSchema,
  topic: z.string().min(1),
  summary: z.string().min(1),
  scenario: z.string().min(1),
  focus: z.array(z.string().min(1)),
  estimatedMinutes: z.number().int().min(1),
  passScore: z.number().int().min(0).max(100),
  turns: z.array(ConversationTurnSchema).min(1),
})
export type ConversationScenario = z.infer<typeof ConversationScenarioSchema>

export const ConversationScenariosSchema = z.array(ConversationScenarioSchema).min(1)

// ---- whole pronunciation pack ----

export const PronunciationPackSchema = z.object({
  meta: PackMetaSchema,
  phonemes: PhonemeCatalogSchema,
  modules: PronunciationModulesSchema,
  targets: PracticeTargetsSchema,
  conversations: ConversationScenariosSchema,
})
export type PronunciationPack = z.infer<typeof PronunciationPackSchema>

export const PACK_IDS = { sprigoSyllabus: 'sprigo-en-syllabus', cadencePronunciation: 'cadence-pronunciation' } as const
